actions.script:
def scope = ec.service.sync().name('zenith.pos.KotServices.get#BillingScope').call()?.scope
offlineCounters = []
offlineReceipts = []
syncedToday = 0
if (!scope?.allowed) return
offlineOrganizationId = scope.organizationPartyId
def shopScope = ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call()
if (shopScope==null || ec.message.hasError()) return
def shop = shopScope.activeShopId
def terminals = ec.entity.find('zenith.erp.pos.PosTerminal')
    .condition([organizationPartyId:offlineOrganizationId,isActive:'Y'])
if (shop) terminals.condition('facilityId',shop)
offlineCounters = terminals.orderBy('terminalName,terminalId').list()
if (scope.terminalRestricted) offlineCounters = offlineCounters.findAll { it.terminalId in scope.allowedTerminalIds }
offlineCounterNames = offlineCounters.collectEntries { [(it.terminalId):it.terminalName ?: it.terminalId] }
if (!offlineCounterNames) return
def todayStart = ec.l10n.parseTimestamp(ec.l10n.format(ec.user.nowTimestamp,'yyyy-MM-dd') + ' 00:00:00','yyyy-MM-dd HH:mm:ss')
for (def entityName in ['KotOfflineDraftSync','KotOfflineSaleSync']) {
    def findReceipts = {
        def find = ec.entity.find('zenith.erp.pos.' + entityName)
            .condition('organizationPartyId',offlineOrganizationId)
            .condition('terminalId','in',offlineCounterNames.keySet() as List)
        if (scope.terminalRestricted) find.condition('userId',ec.user.userId)
        return find
    }
    syncedToday += findReceipts().condition('syncedDate','greater-equals',todayStart).count()
    offlineReceipts.addAll(findReceipts().orderBy('-syncedDate').limit(20).list().collect { receipt ->
        [kotNumber:receipt.kotNumber, terminalId:receipt.terminalId, syncedDate:receipt.syncedDate,
            billNumber:entityName=='KotOfflineSaleSync' ? receipt.billNumber : null,
            held:entityName=='KotOfflineDraftSync']
    })
}
offlineReceipts = offlineReceipts.sort { left, right -> right.syncedDate <=> left.syncedDate }.take(20)
